const payload = $input.item.json.body || $input.item.json;
const alerts = Array.isArray(payload.alerts) ? payload.alerts : [payload];

const normalized = alerts.map((alert, idx) => {
  const labels = alert.labels || {};
  const annotations = alert.annotations || {};
  const alertname = labels.alertname || 'PrometheusAlert';
  const service_name = labels.service || labels.job || 'synapse-service';
  const severity = (labels.severity || 'warning').toLowerCase();
  const instance = labels.instance || 'synapse-host';

  let failure_type = 'service_crash';
  if (alertname.toLowerCase().includes('memory')) {
    failure_type = 'memory_leak';
  } else if (alertname.toLowerCase().includes('disk')) {
    failure_type = 'disk_exhaustion';
  } else if (alertname.toLowerCase().includes('network')) {
    failure_type = 'network_degradation';
  } else if (alertname.toLowerCase().includes('down') || alertname.toLowerCase().includes('crash')) {
    failure_type = 'service_crash';
  } else if (alertname.toLowerCase().includes('risk')) {
    failure_type = 'memory_leak';
  }

  const risk_score = severity === 'critical' ? 91.5 : (severity === 'warning' ? 68.0 : 45.0);
  const routing_decision = severity === 'critical' ? 'auto_remediate' : 'escalate';
  const incident_id = `PROM-${Date.now()}-${idx + 1}`;

  return {
    incident_id,
    source: 'prometheus-alertmanager',
    alertname,
    severity,
    service_name,
    target_host: instance,
    predicted_failure_type: failure_type,
    risk_score,
    routing_decision,
    summary: annotations.summary || alertname,
    description: annotations.description || 'Prometheus alert firing',
    labels,
    annotations,
    timestamp: new Date().toISOString()
  };
});

return normalized.map(item => ({ json: item }));
